function LeadForm({ city, service }) {
  const [form, setForm] = useState({ business_name: '', city: city || '', phone: '', email: '' });
  const [submitting, setSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSubmitting(true);
    try {
      // Save the complete submission through NTA Unified Intake
      await invokeVerifiedPublicFunction('ntaUnifiedIntake', {
        submission_type: 'service_location_inquiry',
        mapping_confidence: 'hardcoded',
        mapping_notes: `ServiceLocation.jsx; service_slug=${service}`,
        detected_route: window.location.pathname,
        detected_component: 'ServiceLocation',
        source_system: 'website',
        source_page: `service-location:${service}:${city}`,
        service_slug: service,
        business_name: form.business_name,
        email: form.email,
        phone: form.phone,
        city: form.city || city || '',
        notes: `Service: ${service}`,
        priority: 'medium',
        is_high_intent: true,
      });

      setSubmitted(true);
    } catch (err) {
      console.error('Lead submit error:', err);
    } finally {
      setSubmitting(false);
    }
  };

  if (submitted) {
    return (
      <div className="text-center py-8">
        <CheckCircle className="w-12 h-12 text-emerald-400 mx-auto mb-4" />
        <h3 className="text-white font-bold text-xl mb-2">We'll be in touch!</h3>
        <p className="text-slate-300">Thanks — a member of our team will reach out within 1 business day.</p>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} className="space-y-4">
      <input
        type="text"
        placeholder="Business Name *"
        required
        value={form.business_name}
        onChange={e => setForm({ ...form, business_name: e.target.value })}
        className="w-full bg-slate-800 border border-slate-700 text-white rounded-lg px-4 py-3 text-sm focus:outline-none focus:border-violet-500"
      />
      <input
        type="text"
        placeholder="Your City *"
        required
        value={form.city}
        onChange={e => setForm({ ...form, city: e.target.value })}
        className="w-full bg-slate-800 border border-slate-700 text-white rounded-lg px-4 py-3 text-sm focus:outline-none focus:border-violet-500"
      />
      <input
        type="tel"
        placeholder="Phone Number"
        value={form.phone}
        onChange={e => setForm({ ...form, phone: e.target.value })}
        className="w-full bg-slate-800 border border-slate-700 text-white rounded-lg px-4 py-3 text-sm focus:outline-none focus:border-violet-500"
      />
      <input
        type="email"
        placeholder="Email Address *"
        required
        value={form.email}
        onChange={e => setForm({ ...form, email: e.target.value })}
        className="w-full bg-slate-800 border border-slate-700 text-white rounded-lg px-4 py-3 text-sm focus:outline-none focus:border-violet-500"
      />
      <button
        type="submit"
        disabled={submitting}
        className="w-full bg-violet-600 hover:bg-violet-500 disabled:opacity-50 text-white font-bold py-3 rounded-lg transition-colors"
      >
        {submitting ? 'Sending...' : 'Get Started →'}
      </button>
      <p className="text-slate-500 text-xs text-center">No credit card required. Free consultation.</p>
    </form>
  );
}

