import { toast } from 'sonner';
import { createPageUrl } from '../utils';
import Header from '../components/landing/Header';
import Footer from '../components/landing/Footer';
import TestModeBanner from '../components/TestModeBanner';

export default function AdaIntake() {
  const navigate = useNavigate();
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isTestMode, setIsTestMode] = useState(false);
  const [formData, setFormData] = useState({
    full_name: '',
    business_name: '',
    email: '',
    phone: '',
    website_url: '',
    city: '',
    state: '',
    nonprofit: false,
    number_of_locations: '1',
    site_type: 'service business',
    approximate_pages: '1-10',
    industry: '',
    notes: '',
    package: 'Growth'
  });

  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const packageParam = urlParams.get('package');
    const nonprofitParam = urlParams.get('nonprofit');

    if (packageParam) {
      setFormData(prev => ({ ...prev, package: packageParam }));
    }
    if (nonprofitParam === 'true') {
      setFormData(prev => ({ ...prev, nonprofit: true }));
    }

    checkTestMode();
  }, []);

  const checkTestMode = async () => {
    try {
      const settings = await base44.entities.AppSettings.list();
      if (settings.length > 0 && settings[0].test_mode_enabled) {
        setIsTestMode(true);
      }
    } catch (error) {
      console.log('Error checking test mode:', error);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);

    try {
      // Mirror to NTA Unified Intake (non-blocking)
      invokeVerifiedPublicFunction('ntaUnifiedIntake', {
        submission_type: 'ada_intake_form',
        offer_type: 'ada_compliance',
        mapping_confidence: 'hardcoded',
        mapping_notes: 'AdaIntake.jsx /ada-intake hardcoded',
        detected_route: '/ada-intake',
        detected_component: 'AdaIntake',
        source_system: 'ada_funnel',
        source_page: '/ada-intake',
        name: formData.full_name,
        business_name: formData.business_name,
        email: formData.email,
        phone: formData.phone,
        website: formData.website_url,
        city: formData.city,
        state: formData.state,
        notes: formData.notes || '',
        selected_package: formData.package,
        priority: 'high',
        is_high_intent: true,
      }).catch(err => console.warn('[AdaIntake] NTA mirror failed:', err.message));

      const lead = await base44.entities.AdaLead.create({
        ...formData,
        status: 'new',
        setup_price: 0,
        monthly_price: 0,
        multiplier: 1.0
      });

      // Track form submission activity
      try {
        await base44.entities.LeadActivity.create({
          lead_id: lead.id,
          activity_type: 'form_submission',
          page_url: window.location.href,
          details: `Submitted intake form for ${formData.package} package`,
          metadata: {
            package: formData.package,
            nonprofit: formData.nonprofit,
            test_mode: isTestMode
          }
        });
      } catch (e) {
        console.log('Activity tracking failed:', e);
      }

      await base44.functions.invoke('adaIntakeWebhook', {
        event: 'ada_intake_submitted',
        lead_id: lead.id,
        ...formData
      });

      navigate(createPageUrl('AdaQuote') + `?lead_id=${lead.id}`);
    } catch (error) {
      console.error('Intake submission error:', error);
      toast.error('Something went wrong. Please try again or call 641-420-8816');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div className="min-h-screen bg-white">
      <TestModeBanner />
      <Header onCTAClick={() => {}} />

      <section className="pt-32 pb-20 bg-gradient-to-br from-slate-50 to-white">
        <div className="max-w-3xl mx-auto px-6">
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            className="text-center mb-12"
          >
            <div className="inline-flex items-center gap-2 px-4 py-2 bg-blue-100 rounded-full mb-6">
              <Shield className="w-4 h-4 text-blue-600" />
              <span className="text-sm font-semibold text-blue-900">ADA Intake Form</span>
            </div>
            <h1 className="text-4xl font-bold text-slate-900 mb-4">
              Request Your ADA Accessibility Review
            </h1>
            <p className="text-lg text-slate-600">
              Package: <span className="font-bold text-blue-600">{formData.package}</span>
              {formData.nonprofit && <span className="ml-2 text-green-600">(Nonprofit Pricing)</span>}
            </p>
          </motion.div>

          <form onSubmit={handleSubmit} className="bg-white rounded-2xl border-2 border-slate-200 p-8 space-y-6">
            <div className="grid md:grid-cols-2 gap-6">
              <div>
                <Label htmlFor="full_name">Full Name *</Label>
                <Input
                  id="full_name"
                  required
                  value={formData.full_name}
                  onChange={(e) => setFormData({ ...formData, full_name: e.target.value })}
                />
              </div>
              <div>
                <Label htmlFor="business_name">Business Name *</Label>
                <Input
                  id="business_name"
                  required
                  value={formData.business_name}
                  onChange={(e) => setFormData({ ...formData, business_name: e.target.value })}
                />
              </div>
            </div>

            <div className="grid md:grid-cols-2 gap-6">
              <div>
                <Label htmlFor="email">Email *</Label>
                <Input
                  id="email"
                  type="email"
                  required
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                />
              </div>
              <div>
                <Label htmlFor="phone">Phone *</Label>
                <Input
                  id="phone"
                  type="tel"
                  required
                  value={formData.phone}
                  onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                />
              </div>
            </div>

            <div>
              <Label htmlFor="website_url">Website URL *</Label>
              <Input
                id="website_url"
                type="url"
                required
                value={formData.website_url}
                onChange={(e) => setFormData({ ...formData, website_url: e.target.value })}
                placeholder="https://example.com"
              />
            </div>

            <div className="grid md:grid-cols-2 gap-6">
              <div>
                <Label htmlFor="city">City *</Label>
                <Input
                  id="city"
                  required
                  value={formData.city}
                  onChange={(e) => setFormData({ ...formData, city: e.target.value })}
                />
              </div>
              <div>
                <Label htmlFor="state">State *</Label>
                <Input
                  id="state"
                  required
                  value={formData.state}
                  onChange={(e) => setFormData({ ...formData, state: e.target.value })}
                  placeholder="IA"
                />
              </div>
            </div>

            <div className="flex items-center gap-2">
              <Checkbox
                id="nonprofit"
                checked={formData.nonprofit}
                onCheckedChange={(checked) => setFormData({ ...formData, nonprofit: checked })}
              />
              <Label htmlFor="nonprofit" className="cursor-pointer">
                We are a nonprofit, church, or community organization
              </Label>
            </div>

            <div className="grid md:grid-cols-2 gap-6">
              <div>
                <Label htmlFor="number_of_locations">Number of Locations</Label>
                <Select value={formData.number_of_locations} onValueChange={(value) => setFormData({ ...formData, number_of_locations: value })}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="1">1</SelectItem>
                    <SelectItem value="2-3">2-3</SelectItem>
                    <SelectItem value="4-10">4-10</SelectItem>
                    <SelectItem value="11+">11+</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label htmlFor="site_type">Website Type</Label>
                <Select value={formData.site_type} onValueChange={(value) => setFormData({ ...formData, site_type: value })}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="brochure">Brochure / Info</SelectItem>
                    <SelectItem value="service business">Service Business</SelectItem>
                    <SelectItem value="ecommerce">E-commerce</SelectItem>
                    <SelectItem value="booking/scheduling">Booking / Scheduling</SelectItem>
                    <SelectItem value="other">Other</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="grid md:grid-cols-2 gap-6">
              <div>
                <Label htmlFor="approximate_pages">Approximate Pages</Label>
                <Select value={formData.approximate_pages} onValueChange={(value) => setFormData({ ...formData, approximate_pages: value })}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="1-10">1-10</SelectItem>
                    <SelectItem value="11-15">11-15</SelectItem>
                    <SelectItem value="16-30">16-30</SelectItem>
                    <SelectItem value="31+">31+</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label htmlFor="industry">Industry</Label>
                <Select value={formData.industry} onValueChange={(value) => setFormData({ ...formData, industry: value })}>
                  <SelectTrigger>
                    <SelectValue placeholder="Select industry" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="home services">Home Services</SelectItem>
                    <SelectItem value="medical">Medical / Healthcare</SelectItem>
                    <SelectItem value="legal">Legal</SelectItem>
                    <SelectItem value="accounting">Accounting</SelectItem>
                    <SelectItem value="hospitality">Hospitality</SelectItem>
                    <SelectItem value="education">Education</SelectItem>
                    <SelectItem value="nonprofit">Nonprofit</SelectItem>
                    <SelectItem value="retail">Retail</SelectItem>
                    <SelectItem value="other">Other</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div>
              <Label htmlFor="notes">Additional Notes</Label>
              <Textarea
                id="notes"
                value={formData.notes}
                onChange={(e) => setFormData({ ...formData, notes: e.target.value })}
                placeholder="Any specific concerns or questions?"
                rows={4}
              />
            </div>
            <div>
  <Label htmlFor="package">ADA Package</Label>
  <Select
    value={formData.package}
    onValueChange={(value) => setFormData({ ...formData, package: value })}
  >
    <SelectTrigger>
      <SelectValue placeholder="Select ADA package" />
    </SelectTrigger>
    <SelectContent>
      <SelectItem value="Starter">Starter</SelectItem>
      <SelectItem value="Growth">Growth</SelectItem>
      <SelectItem value="Authority">Authority</SelectItem>
    </SelectContent>
  </Select>
</div>


            <Button
              type="submit"
              disabled={isSubmitting}
              className="w-full bg-gradient-to-r from-blue-600 to-purple-600 hover:from-blue-700 hover:to-purple-700 text-white py-6 text-lg"
            >
              {isSubmitting ? (
                <>
                  <Loader2 className="mr-2 w-5 h-5 animate-spin" />
                  Submitting...
                </>
              ) : (
                'Submit ADA Request'
              )}
            </Button>

            <p className="text-sm text-slate-500 text-center">
              We'll review your site and send you a detailed quote within 1 business day.
            </p>
          </form>
        </div>
      </section>

      <Footer />
    </div>
  );
}

import { invokeVerifiedPublicFunction } from '@/lib/publicVerification';
import React, { useState } from 'react';
import { ArrowRight, ChevronDown, ChevronUp } from 'lucide-react';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import StartTrust from './StartTrust';

const INDUSTRIES = [
  'HVAC', 'Plumbing', 'Restaurant', 'Contractor', 'Electrician',
  'Roofing', 'Auto Repair', 'Other Local Service Business', 'Marketing / Agency / Other',
];

const GOALS = [
  { value: 'leads', label: 'Get more leads' },
  { value: 'visibility', label: 'Improve visibility online' },
  { value: 'consistency', label: 'Stay consistent with marketing' },
  { value: 'content_video', label: 'Create more content and videos' },
  { value: 'replace_marketing', label: 'Replace my current marketing approach' },
];

const SOURCES = [
  { value: 'google', label: 'Google Search' },
  { value: 'facebook', label: 'Facebook' },
  { value: 'youtube', label: 'YouTube' },
  { value: 'referral', label: 'Referral' },
  { value: 'email', label: 'Email' },
  { value: 'demo_tool', label: 'Demo / Tool Page' },
  { value: 'other', label: 'Other' },
];

const FIELD = ({ label, children, required }) => (
  <div>
    <Label className="text-slate-300 text-sm mb-1.5 block">
      {label}{required && <span className="text-violet-400 ml-0.5">*</span>}
    </Label>
    {children}
  </div>
);

const inputCls = "bg-slate-800 border-slate-700 text-white placeholder:text-slate-500 focus:border-violet-500 focus:ring-violet-500/20";
const selectCls = "w-full bg-slate-800 border border-slate-700 text-white rounded-md px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-violet-500/30 focus:border-violet-500";

export default function StartForm({ sourceData = {}, onSuccess }) {
  const [step, setStep] = useState(1);
  const [showExtra, setShowExtra] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [errors, setErrors] = useState({});
  // Anti-spam: honeypot + page-load timestamp
  const [_hp, setHp] = useState('');
  const [pageLoadTs] = useState(() => Date.now());

  const [form, setForm] = useState({
    // Step 1
    business_name: '',
    full_name: '',
    email: '',
    phone: '',
    industry: '',
    city: '',
    state: '',
    primary_goal: '',
    // Step 2 / extras
    website_url: '',
    how_did_you_find_us: '',
    notes: '',
    ...sourceData,
  });

  const set = (field, value) => {
    setForm(prev => ({ ...prev, [field]: value }));
    if (errors[field]) setErrors(prev => ({ ...prev, [field]: null }));
  };

  const validateStep1 = () => {
    const errs = {};
    if (!form.business_name.trim()) errs.business_name = 'Required';
    if (!form.full_name.trim()) errs.full_name = 'Required';
    if (!form.email.trim() || !/\S+@\S+\.\S+/.test(form.email)) errs.email = 'Valid email required';
    if (!form.industry) errs.industry = 'Required';
    if (!form.city.trim()) errs.city = 'Required';
    if (!form.state.trim()) errs.state = 'Required';
    if (!form.primary_goal) errs.primary_goal = 'Required';
    return errs;
  };

  const handleStep1 = () => {
    const errs = validateStep1();
    if (Object.keys(errs).length) { setErrors(errs); return; }
    setStep(2);
    window.scrollTo({ top: document.getElementById('start-form')?.offsetTop - 80, behavior: 'smooth' });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSubmitting(true);
    try {
      const { base44 } = await import('@/api/base44Client');

      // STEP 1 — Save the complete submission and CRM records atomically
      await invokeVerifiedPublicFunction('ntaUnifiedIntake', {
        submission_type: 'trial_signup',
        offer_type: 'trial_onboarding',
        mapping_confidence: 'hardcoded',
        mapping_notes: 'StartForm.jsx /start hardcoded',
        detected_route: sourceData.source_page || '/start',
        detected_component: 'StartForm',
        source_system: 'website',
        source_page: sourceData.source_page || '/start',
        source_campaign: sourceData.source_campaign || '',
        name: form.full_name,
        business_name: form.business_name,
        email: form.email,
        phone: form.phone,
        website: form.website_url,
        city: form.city,
        state: form.state,
        notes: `Industry: ${form.industry} | Goal: ${form.primary_goal}${form.notes ? ' | ' + form.notes : ''}`,
        priority: 'high',
        is_high_intent: true,
        skip_webhook: true,
        anti_spam: {
          honeypot: _hp,
          form_started_at: pageLoadTs,
        },
      });

      // STEP 3 — Create TrialAccount record
      const slug = form.business_name.toLowerCase().replace(/[^a-z0-9]+/g, '-') + '-' + Date.now();
      const trialData = {
        name: form.business_name,
        slug,
        full_name: form.full_name,
        email: form.email,
        phone: form.phone,
        industry: form.industry,
        location_city: form.city,
        location_state: form.state,
        website_url: form.website_url,
        primary_goal: form.primary_goal,
        how_did_you_find_us: form.how_did_you_find_us || 'other',
        source_page: sourceData.source_page || 'start',
        source_tool: sourceData.source_tool || '',
        source_campaign: sourceData.source_campaign || '',
        notes: form.notes,
        trial_status: 'submitted',
        trial_start_at: new Date().toISOString(),
        trial_end_at: new Date(Date.now() + 14 * 24 * 60 * 60 * 1000).toISOString(),
      };
      const trial = await base44.entities.TrialAccount.create(trialData);

      // 3. Create BusinessProfile
      const bp = await base44.entities.BusinessProfile.create({
        business_name: form.business_name,
        business_slug: slug,
        website_url: form.website_url,
        industry_slug: form.industry.toLowerCase().replace(/[^a-z0-9]+/g, '-'),
        city: form.city,
        state: form.state,
        primary_goal: form.primary_goal === 'leads' ? 'leads'
          : form.primary_goal === 'visibility' ? 'visibility'
          : form.primary_goal === 'consistency' ? 'retention'
          : 'traffic',
        status: 'active',
      });

      // 4. Update TrialAccount with BusinessProfile ID
      await base44.entities.TrialAccount.update(trial.id, { business_profile_id: bp.id });

      // 5. Send internal notification email
      await base44.integrations.Core.SendEmail({
        from_name: 'NTA — New Trial Signup',
        to: 'rick@newtechadvertising.com',
        subject: `🚀 New Trial: ${form.business_name} (${form.industry})`,
        body: `New trial started!\n\nBusiness: ${form.business_name}\nContact: ${form.full_name}\nEmail: ${form.email}\nPhone: ${form.phone}\nIndustry: ${form.industry}\nLocation: ${form.city}, ${form.state}\nGoal: ${form.primary_goal}\nWebsite: ${form.website_url}\nSource: ${sourceData.source_page || 'start'}\nNotes: ${form.notes}`,
      });

      // 6. Kick off the intelligence + provisioning pipeline
      base44.functions.invoke('onTrialSubmitted', { trial_id: trial.id }).catch(err =>
        console.warn('[StartForm] onTrialSubmitted background call failed:', err.message)
      );

      onSuccess({ trialId: trial.id, businessProfileId: bp.id, provisioningStatus: 'queued' });
    } catch (err) {
      console.error('Trial submission error:', err);
      setSubmitting(false);
    }
  };

  const errMsg = (field) => errors[field] ? (
    <p className="text-red-400 text-xs mt-1">{errors[field]}</p>
  ) : null;

  return (
    <div id="start-form" className="bg-slate-900 border border-slate-800 rounded-2xl p-6 sm:p-8">
      {/* Progress */}
      <div className="flex items-center gap-3 mb-7">
        {[1, 2].map(n => (
          <React.Fragment key={n}>
            <div className={`flex items-center gap-2 ${step >= n ? 'text-white' : 'text-slate-600'}`}>
              <div className={`w-7 h-7 rounded-full flex items-center justify-center text-xs font-bold border-2 transition-all ${step >= n ? 'bg-violet-600 border-violet-600 text-white' : 'border-slate-700 text-slate-600'}`}>
                {n}
              </div>
              <span className="text-sm font-medium hidden sm:inline">
                {n === 1 ? 'Your Business' : 'A Few More Details'}
              </span>
            </div>
            {n < 2 && <div className={`flex-1 h-px ${step > 1 ? 'bg-violet-600' : 'bg-slate-800'}`} />}
          </React.Fragment>
        ))}
      </div>

      <form onSubmit={handleSubmit}>
        {/* Anti-spam honeypot — hidden from real users */}
        <div aria-hidden="true" style={{ position: 'absolute', left: '-9999px', top: '-9999px', opacity: 0, height: 0, overflow: 'hidden' }}>
          <label htmlFor="company_url">Company URL</label>
          <input id="company_url" name="company_url" type="text" tabIndex={-1} autoComplete="off" value={_hp} onChange={e => setHp(e.target.value)} />
        </div>
        {/* ── STEP 1 ─────────────────────────────────── */}
        {step === 1 && (
          <div className="space-y-5">
            <div className="grid sm:grid-cols-2 gap-5">
              <FIELD label="Business Name" required>
                <Input value={form.business_name} onChange={e => set('business_name', e.target.value)} placeholder="Smith Plumbing" className={inputCls} />
                {errMsg('business_name')}
              </FIELD>
              <FIELD label="Your Name" required>
                <Input value={form.full_name} onChange={e => set('full_name', e.target.value)} placeholder="Jane Smith" className={inputCls} />
                {errMsg('full_name')}
              </FIELD>
              <FIELD label="Email" required>
                <Input type="email" value={form.email} onChange={e => set('email', e.target.value)} placeholder="jane@smithplumbing.com" className={inputCls} />
                {errMsg('email')}
              </FIELD>
              <FIELD label="Phone">
                <Input type="tel" value={form.phone} onChange={e => set('phone', e.target.value)} placeholder="(555) 123-4567" className={inputCls} />
              </FIELD>
            </div>

            <FIELD label="Industry" required>
              <select value={form.industry} onChange={e => set('industry', e.target.value)} className={selectCls}>
                <option value="">Select your industry…</option>
                {INDUSTRIES.map(i => <option key={i} value={i}>{i}</option>)}
              </select>
              {errMsg('industry')}
            </FIELD>

            <div className="grid sm:grid-cols-2 gap-5">
              <FIELD label="City" required>
                <Input value={form.city} onChange={e => set('city', e.target.value)} placeholder="Des Moines" className={inputCls} />
                {errMsg('city')}
              </FIELD>
              <FIELD label="State" required>
                <Input value={form.state} onChange={e => set('state', e.target.value)} placeholder="IA" className={inputCls} />
                {errMsg('state')}
              </FIELD>
            </div>

            <FIELD label="What's your primary marketing goal?" required>
              <select value={form.primary_goal} onChange={e => set('primary_goal', e.target.value)} className={selectCls}>
                <option value="">Select your goal…</option>
                {GOALS.map(g => <option key={g.value} value={g.value}>{g.label}</option>)}
              </select>
              {errMsg('primary_goal')}
            </FIELD>

            <Button
              type="button"
              onClick={handleStep1}
              className="w-full bg-violet-600 hover:bg-violet-500 text-white font-bold py-3 h-auto text-base rounded-xl shadow-lg shadow-violet-600/30"
            >
              Continue <ArrowRight className="w-5 h-5 ml-2" />
            </Button>
          </div>
        )}

        {/* ── STEP 2 ─────────────────────────────────── */}
        {step === 2 && (
          <div className="space-y-5">
            <FIELD label="Business Website">
              <Input type="url" value={form.website_url} onChange={e => set('website_url', e.target.value)} placeholder="https://smithplumbing.com" className={inputCls} />
            </FIELD>

            <FIELD label="How did you find us?">
              <select value={form.how_did_you_find_us} onChange={e => set('how_did_you_find_us', e.target.value)} className={selectCls}>
                <option value="">Select…</option>
                {SOURCES.map(s => <option key={s.value} value={s.value}>{s.label}</option>)}
              </select>
            </FIELD>

            {/* Optional extras */}
            <button
              type="button"
              onClick={() => setShowExtra(!showExtra)}
              className="flex items-center gap-2 text-slate-400 hover:text-white text-sm transition-colors"
            >
              {showExtra ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
              Add a note about your business (optional)
            </button>

            {showExtra && (
              <textarea
                value={form.notes}
                onChange={e => set('notes', e.target.value)}
                rows={3}
                placeholder="Tell us anything that would help us set up your marketing system better…"
